_engine = None

# Token the VPN renderers emit in place of a real PSK: __GATESHIFT_PSK_<hash>__.
# Carries the tunnel identity (vpn_hash) but no secret, so it is safe in the
# generated/previewed/audited config and round-trips through the browser. The
# real PSK is substituted server-side, just before the live push (deploy_push).
_PSK_TOKEN_RE = re.compile(r"__GATESHIFT_PSK_([0-9a-fA-F]+)__")
_VPN_PSK_PLACEHOLDER = "GATESHIFT-PLACEHOLDER-PSK-CHANGE-ME"


def _inject_push_secrets(config: dict, source_id: int, platform: str) -> dict:
    """Resolve __GATESHIFT_PSK_<hash>__ tokens in a freshly-received push config
    to the operator's stored PSKs (decrypted server-side, in memory only). A
    tunnel with no stored PSK - or storage being unconfigured - resolves to the
    placeholder, exactly as before. Single-pass substitution so an injected
    secret is never re-scanned. Returns a NEW dict; the caller's token-config
    (the one that round-tripped the browser / would be audited) is untouched.

    The secret is escaped for the CONFIG FORMAT it lands in so an arbitrary PSK
    (quotes, backslashes, angle brackets) can't corrupt the payload: PA config
    sections are XML, Forti/CP sections are JSON strings (json.loads'd by the
    push). The placeholder is plain ASCII → safe either way."""
    if not isinstance(config, dict) or not config:
        return config
    # Fast-path: nothing to do unless a token is actually present.
    if not any(isinstance(v, str) and "__GATESHIFT_PSK_" in v for v in config.values()):
        return config
    secrets: dict[str, str] = {}
    try:
        with get_engine().connect() as conn:
            rows = conn.execute(text(
                "SELECT LOWER(HEX(vpn_hash)), secret_enc FROM fw_vpn_tunnel_secrets "
                "WHERE device_id = :d"
            ), {"d": source_id}).fetchall()
        for h, enc in rows:
            pt = secrets_util.decrypt(enc)
            if pt is not None:
                secrets[h.lower()] = pt
    except Exception:
        secrets = {}

    def _escape(s: str) -> str:
        if platform == "panw":
            return html_mod.escape(s, quote=False)   # XML element text: & < >
        # Forti/CP: embed inside an existing JSON string literal → escape and
        # strip json.dumps' surrounding quotes.
        return json.dumps(s)[1:-1]

    def _sub(m: "re.Match") -> str:
        pt = secrets.get(m.group(1).lower())
        return _escape(pt) if pt is not None else _VPN_PSK_PLACEHOLDER

    return {
        k: (_PSK_TOKEN_RE.sub(_sub, v) if isinstance(v, str) else v)
        for k, v in config.items()
    }


def _load_push_certs(source_id: int) -> dict:
    """Build the VPN identity-cert map for a push: {vpn_hash_hex: {cert_name,
    cert_pem, key_pem}}, decrypting the stored key server-side (in memory only).
    Empty if storage is unconfigured / nothing uploaded / a key won't decrypt.
    Passed to driver.push() so the cert-import step can provision the gateway
    identity. The key never touches the client, the DB-in-clear, or the audit."""
    out: dict[str, dict] = {}
    try:
        with get_engine().connect() as conn:
            rows = conn.execute(text(
                "SELECT LOWER(HEX(vpn_hash)), cert_name, cert_pem, key_enc "
                "FROM fw_vpn_tunnel_certs WHERE device_id = :d"
            ), {"d": source_id}).fetchall()
    except Exception:
        return out
    for h, name, cert_pem, key_enc in rows:
        key_pem = secrets_util.decrypt(key_enc)
        if key_pem and name and cert_pem:
            out[h.lower()] = {"cert_name": name, "cert_pem": cert_pem, "key_pem": key_pem}
    return out


def get_engine():
    global _engine
    if _engine is None:
        # Prefer the unprivileged application account (DB_USER/DB_PASSWORD,
        # granted only on this schema). Falls back to root for installations
        # that predate the dedicated user, so an upgrade doesn't strand them.
        user = os.getenv("DB_USER") or "root"
        pw   = (os.getenv("DB_PASSWORD")
                if os.getenv("DB_USER")
                else None) or os.getenv("MARIADB_ROOT_PASSWORD", "")
        host = os.getenv("DB_HOST", "mariadb")
        port = os.getenv("DB_PORT", "3306")
        name = os.getenv("DB_NAME", "gateshift")
        _engine = create_engine(
            f"mysql+pymysql://{urllib.parse.quote_plus(user)}:{urllib.parse.quote_plus(pw)}"
            f"@{host}:{port}/{name}",
            pool_pre_ping=True,
        )
    return _engine


