# Private IP ranges for internet_public detection
_PRIVATE = """(
  INET_ATON({col}) BETWEEN INET_ATON('10.0.0.0')    AND INET_ATON('10.255.255.255')
  OR INET_ATON({col}) BETWEEN INET_ATON('172.16.0.0')  AND INET_ATON('172.31.255.255')
  OR INET_ATON({col}) BETWEEN INET_ATON('192.168.0.0') AND INET_ATON('192.168.255.255')
  OR INET_ATON({col}) BETWEEN INET_ATON('127.0.0.0')   AND INET_ATON('127.255.255.255')
  OR INET_ATON({col}) BETWEEN INET_ATON('169.254.0.0') AND INET_ATON('169.254.255.255')
)"""

# App signature lookup - prefer most specific range, pick first name alphabetically on ties
_SIG_JOIN = """LEFT JOIN (
    SELECT proto, port_from AS port, MIN(app_name) AS app_name
    FROM fw_app_signatures
    WHERE port_from = port_to
    GROUP BY proto, port_from
) sig ON sig.proto = r.proto AND sig.port = r.dst_port"""


def load_config(conn) -> dict:
    try:
        rows = conn.execute(
            text("SELECT job_name, enabled, params FROM fw_pipeline_config")
        ).fetchall()
        return {r[0]: {"enabled": bool(r[1]), "params": json.loads(r[2] or "{}")} for r in rows}
    except Exception:
        return {}


def get_zone_status(conn) -> dict:
    """Returns unzoned_count - number of sources+destinations without a zone after last generate."""
    try:
        row = conn.execute(text(
            "SELECT params FROM fw_pipeline_config WHERE job_name = '_zone_status' LIMIT 1"
        )).fetchone()
        if row:
            p = json.loads(row[0] or "{}")
            return {"unzoned_count": int(p.get("unzoned_count", 0))}
    except Exception:
        pass
    return {"unzoned_count": -1}  # -1 = never generated, treat as unknown


def get_has_logs(conn) -> bool:
    try:
        row = conn.execute(text("SELECT 1 FROM fw_flows LIMIT 1")).fetchone()
        return row is not None
    except Exception:
        return False


def _migrate_endpoint_pairs_schema():
    """Drop src_hash column from fw_rules_endpoint_pairs if it still exists (schema v1 → v2)."""
    try:
        with get_engine().begin() as conn:
            has_col = conn.execute(text(
                "SELECT 1 FROM information_schema.COLUMNS "
                "WHERE TABLE_SCHEMA = DATABASE() "
                "  AND TABLE_NAME = 'fw_rules_endpoint_pairs' "
                "  AND COLUMN_NAME = 'src_hash'"
            )).fetchone()
            if has_col:
                conn.execute(text("ALTER TABLE fw_rules_endpoint_pairs DROP COLUMN src_hash"))
                conn.execute(text("ALTER TABLE fw_rules_endpoint_pairs DROP INDEX IF EXISTS idx_src_hash"))
    except Exception:
        pass


def _migrate_qf_last_seen_days_to_date():
    """One-shot: convert QF's `max_last_seen_days` (int) to `last_seen_after`
    (date YYYY-MM-DD). Migration-snapshot semantics: an existing N=30
    becomes today-30 as a fixed date - subsequent QF runs no longer roll
    with the calendar. User can re-tune in Org > Access > Accumulate.

    Idempotent: if `last_seen_after` is already set OR `max_last_seen_days`
    isn't present, no-op. Runs once per app start; safe across restarts.
    """
    try:
        import datetime as _dt
        with get_engine().begin() as conn:
            row = conn.execute(text(
                "SELECT params FROM fw_pipeline_config "
                "WHERE job_name = '55_quality_filter'"
            )).fetchone()
            if not row or not row[0]:
                return
            try:
                params = (json.loads(row[0])
                          if isinstance(row[0], str) else (row[0] or {}))
            except Exception:
                return
            if "last_seen_after" in params:
                return  # already migrated
            n_days = params.pop("max_last_seen_days", None)
            if n_days is None:
                return  # nothing to migrate
            try:
                n_days = int(n_days)
            except (TypeError, ValueError):
                n_days = 30
            cutoff = (_dt.date.today() - _dt.timedelta(days=n_days)).isoformat()
            params["last_seen_after"] = cutoff
            conn.execute(text(
                "UPDATE fw_pipeline_config SET params = :p "
                "WHERE job_name = '55_quality_filter'"
            ), {"p": json.dumps(params)})
            print(f"[qf-migrate] max_last_seen_days={n_days} → "
                  f"last_seen_after={cutoff}", flush=True)
    except Exception as e:
        print(f"[qf-migrate] failed: {e}", flush=True)


