def _seed_connected_routes_for_device(conn, device_id: int) -> int:
    """Materialize connected routes (one per interface IP/CIDR) into fw_routes
    for a single device. Connected routes are implicit from interface IPs;
    vendor route APIs (e.g. FortiOS router/static) return only static routes,
    so the bulk fetch-from-target save path won't bring them - call this after
    saving interfaces/routes so Network > Routing isn't empty. Idempotent
    (INSERT IGNORE on the (device_id, prefix, vr_name) UNIQUE key). Returns the
    number of INSERT attempts.
    """
    if not device_id:
        return 0
    rows = conn.execute(text(
        "SELECT interface_name, ip_addresses FROM fw_interfaces "
        "WHERE device_id = :d AND ip_addresses IS NOT NULL AND ip_addresses <> '[]'"
    ), {"d": device_id}).fetchall()
    n = 0
    for iname, ips_raw in rows:
        if not iname:
            continue
        try:
            ips = (json.loads(ips_raw)
                   if isinstance(ips_raw, str) else (ips_raw or []))
        except Exception:
            continue
        for ip_str in ips:
            try:
                net = ipaddress.ip_network(ip_str, strict=False)
            except (ValueError, TypeError):
                continue
            # Connected routes are static by definition (vendor synth on iface
            # IP), not blackhole. INSERT IGNORE no-ops on an existing prefix.
            conn.execute(text("""
                INSERT IGNORE INTO fw_routes
                    (device_id, prefix, prefix_len, ip_from, ip_to,
                     interface_name, vr_name, route_type)
                VALUES (:did, :prefix, :plen, :ip_from, :ip_to,
                        :iface, 'default', 'static')
            """), {
                "did": device_id, "prefix": str(net), "plen": net.prefixlen,
                "ip_from": int(net.network_address),
                "ip_to": int(net.broadcast_address),
                "iface": iname,
            })
            n += 1
    return n


def _backfill_connected_routes():
    """Startup pass: ensure every interface with an IP carries a matching
    connected route in fw_routes, across all devices. Per-device seed lives in
    _seed_connected_routes_for_device (also called from the network-discover
    save path). Run once at startup so ifaces inserted via a route-seed-less
    path aren't invisible in Network > Routing.
    """
    try:
        with get_engine().begin() as conn:
            dids = [r[0] for r in conn.execute(text(
                "SELECT DISTINCT device_id FROM fw_interfaces "
                "WHERE ip_addresses IS NOT NULL AND ip_addresses <> '[]'"
            )).fetchall()]
            for did in dids:
                _seed_connected_routes_for_device(conn, did)
    except Exception as e:
        print(f"[backfill_connected_routes] failed: {e}", flush=True)


