def _ensure_iface_deploy_columns():
    """Per-interface deploy metadata on fw_interfaces.

    - deploy_skip: user chose not to migrate this source interface (1) - push
      skips it.
    - origin: 'import' (came from a source config - has import_interface_name)
      vs 'manual' (user-added extra). Re-derived each startup from the reliable
      import_interface_name signal, so it stays consistent.

    Also drops the retired target_binding column: the iface-consolidation
    ([[iface-consolidation-plan]]) made the canonical interface_name the single
    source of truth (cascade-rename, persisted in fw_interface_overrides), so the
    deploy-time binding mapping no longer exists.
    """
    for ddl in (
        "ALTER TABLE fw_interfaces "
        "ADD COLUMN IF NOT EXISTS deploy_skip TINYINT(1) NOT NULL DEFAULT 0",
        "ALTER TABLE fw_interfaces "
        "ADD COLUMN IF NOT EXISTS origin VARCHAR(16) NOT NULL DEFAULT 'import'",
        "ALTER TABLE fw_interfaces DROP COLUMN IF EXISTS target_binding",
    ):
        try:
            with get_engine().begin() as conn:
                conn.execute(text(ddl))
        except Exception as e:
            print(f"[ensure_iface_deploy_columns] DDL failed: {e}", flush=True)
    # origin: imported rows carry import_interface_name; manual extras do not.
    try:
        with get_engine().begin() as conn:
            conn.execute(text(
                "UPDATE fw_interfaces SET origin = "
                "IF(import_interface_name IS NULL OR import_interface_name = '', "
                "'manual', 'import')"
            ))
    except Exception as e:
        print(f"[ensure_iface_deploy_columns] origin backfill failed: {e}", flush=True)


