def _safe_add_columns(tables, coldefs):
    """ADD COLUMN IF NOT EXISTS across `tables`, each ALTER in its OWN
    transaction so a table that doesn't exist yet (fresh install - the
    pipeline tables are created lazily by import/generate) only skips
    itself instead of aborting the whole batch. `coldefs` maps column
    name → full column definition. Mirrors the lifespan-DDL pattern
    (engine.begin() per DDL) - see feedback_lifespan_ddl_pattern.
    """
    eng = get_engine()
    for tbl in tables:
        for col, ddl in coldefs.items():
            try:
                with eng.begin() as conn:
                    conn.execute(text(
                        f"ALTER TABLE {tbl} ADD COLUMN IF NOT EXISTS {col} {ddl}"))
            except Exception:
                pass   # table absent on a fresh DB - a later run adds it


def _ensure_negate_columns():
    """Add negate_source/destination/service TINYINT(1) DEFAULT 0 across the
    consolidated + derived rule tables + fw_nat_rules. Plus ensure the
    fw_rule_negate_overrides table exists.

    Rule-level field negation (PA `<negate-source>yes/no</...>`, Forti
    `srcaddr-negate: "enable"`, CP `source-negate: true`) - per V0 lab-probe
    in project_rule_negation_plan. content_hash is intentionally NOT
    extended with these flags so that toggling them via UI doesn't break
    the override-link (same pattern as `disabled`, `description`).

    Derived tables (filtered/subnet/accumulated/endpoint_pairs) get the
    same columns so SQL-job INSERT-SELECTs can thread them through.
    Endpoint-pairs adds them to GROUP BY → 2 rules with different negate
    flags on identical (src,dst,svc) split into 2 endpoint-rows instead of
    silently merging (per plan-memo conflict-policy decision).
    """
    tables = (
        "fw_imported_rules",
        "fw_flows",
        "fw_rule_candidates",
        "fw_rules_consolidated_1",
        "fw_rules_filtered",
        "fw_rules_subnet",
        "fw_rules_accumulated",
        "fw_rules_endpoint_pairs",
        "fw_nat_rules",
    )
    _safe_add_columns(tables, {c: "TINYINT(1) NOT NULL DEFAULT 0"
                               for c in ("negate_source", "negate_destination", "negate_service")})
    try:
        with get_engine().begin() as conn:
            # Override table for security rules (NAT uses properties JSON slot).
            conn.execute(text("""
                CREATE TABLE IF NOT EXISTS fw_rule_negate_overrides (
                  rule_hash           BINARY(20)            NOT NULL PRIMARY KEY,
                  negate_source       TINYINT(1)            NULL,
                  negate_destination  TINYINT(1)            NULL,
                  negate_service      TINYINT(1)            NULL,
                  source              ENUM('manual','auto') NOT NULL DEFAULT 'manual',
                  updated_at          TIMESTAMP             NOT NULL DEFAULT CURRENT_TIMESTAMP
                                                              ON UPDATE CURRENT_TIMESTAMP
                ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE utf8mb4_unicode_ci
            """))
    except Exception as e:
        print(f"[ensure_negate_columns] failed: {e}", flush=True)


