def _patch_display_param(conn, key: str, value) -> None:
    """Update a single key in the _display config without touching other keys."""
    existing = load_config(conn).get("_display", {}).get("params", {})
    existing[key] = value
    conn.execute(text("""
        INSERT INTO fw_pipeline_config (job_name, enabled, params)
        VALUES ('_display', 1, :p)
        ON DUPLICATE KEY UPDATE params = :p
    """), {"p": json.dumps(existing)})


@app.post("/config/auto-name", response_class=JSONResponse)
async def config_auto_name(request: Request):
    value = 1 if (await request.json()).get("enabled") else 0
    with get_engine().begin() as conn:
        _patch_display_param(conn, "auto_name", value)
    return JSONResponse({"ok": True, "auto_name": value})


