_ORG_PIPELINE_MODULES = frozenset({
    "52_accumulate", "53_subnet", "55_quality_filter", "56_endpoint_pairs",
})


_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _validate_pipeline_params(job_name: str, raw_params: dict) -> tuple[dict, str | None]:
    """Validate a partial params dict against the schema declared for
    `job_name` in _PIPELINE_MODULES. Returns (clean, err). On error,
    `clean` is empty and `err` is a human-readable message.

    Unknown keys are rejected (whitelist). Per-field rules:
      bool  → coerce truthy
      int   → int(); enforce min if declared
      date  → match YYYY-MM-DD (use None to unset)
    """
    schema = next((m for m in PIPELINE_JOBS if m["name"] == job_name), None)
    if not schema:
        return {}, f"no schema for job {job_name!r}"
    by_key = {f["key"]: f for f in (schema.get("params") or [])}
    clean: dict = {}
    for k, v in (raw_params or {}).items():
        f = by_key.get(k)
        if not f:
            return {}, f"unknown param {k!r} for {job_name}"
        ftype = f.get("type")
        if ftype == "bool":
            clean[k] = bool(v)
        elif ftype == "int":
            try:
                iv = int(v)
            except (TypeError, ValueError):
                return {}, f"{k} must be an integer"
            if "min" in f and iv < f["min"]:
                return {}, f"{k} must be ≥ {f['min']}"
            clean[k] = iv
        elif ftype == "date":
            if v in (None, "", "null"):
                clean[k] = None
                continue
            s = str(v).strip()
            if not _DATE_RE.fullmatch(s):
                return {}, f"{k} must be a date YYYY-MM-DD"
            clean[k] = s
        else:
            # string / unknown - pass through
            clean[k] = v if v is not None else None
    return clean, None


@app.post("/config/module/{job_name}", response_class=JSONResponse)
async def config_module_toggle(job_name: str, request: Request):
    """Set the `enabled` flag and/or `params` for a pipeline job.

    Whitelisted to the four modules surfaced by the Org > Access settings
    block (52_accumulate + its three dependent stages). Flipping any of
    these marks needs_generate so the next switch into a rule-viewing
    primary auto-triggers Generate.

    Body fields (both optional):
      enabled: bool - toggle the job
      params:  dict - partial param-merge against the schema; unknown
                      keys rejected, types coerced/validated.
    """
    if job_name not in _ORG_PIPELINE_MODULES:
        return JSONResponse(
            {"error": f"unknown or non-toggleable job: {job_name!r}"},
            status_code=400,
        )
    body = await request.json()
    if not isinstance(body, dict):
        return JSONResponse({"error": "expected JSON object"}, status_code=400)
    has_enabled = "enabled" in body
    has_params  = "params" in body and isinstance(body.get("params"), dict)
    if not has_enabled and not has_params:
        return JSONResponse({"error": "expected enabled and/or params"}, status_code=400)
    enabled = 1 if body.get("enabled") else 0

    clean_params: dict | None = None
    if has_params:
        clean_params, err = _validate_pipeline_params(job_name, body["params"])
        if err:
            return JSONResponse({"error": err}, status_code=400)

    with get_engine().begin() as conn:
        if has_params:
            # JSON_MERGE_PATCH merges the partial update into existing
            # params. NULL existing → JSON_MERGE_PATCH treats it as {}.
            # Toggle-only path keeps the legacy INSERT/UPDATE for
            # backward-compat with existing rows.
            row = conn.execute(text(
                "SELECT params FROM fw_pipeline_config WHERE job_name = :job"
            ), {"job": job_name}).fetchone()
            existing = {}
            if row and row[0]:
                try:
                    existing = (json.loads(row[0])
                                if isinstance(row[0], str) else (row[0] or {}))
                except Exception:
                    existing = {}
            merged = {**existing, **clean_params}
            payload_params = json.dumps(merged)
            if has_enabled:
                conn.execute(text("""
                    INSERT INTO fw_pipeline_config (job_name, enabled, params)
                    VALUES (:job, :enabled, :params)
                    ON DUPLICATE KEY UPDATE enabled = :enabled, params = :params
                """), {"job": job_name, "enabled": enabled, "params": payload_params})
            else:
                conn.execute(text("""
                    INSERT INTO fw_pipeline_config (job_name, enabled, params)
                    VALUES (:job, 0, :params)
                    ON DUPLICATE KEY UPDATE params = :params
                """), {"job": job_name, "params": payload_params})
        else:
            conn.execute(text("""
                INSERT INTO fw_pipeline_config (job_name, enabled, params)
                VALUES (:job, :enabled, NULL)
                ON DUPLICATE KEY UPDATE enabled = :enabled
            """), {"job": job_name, "enabled": enabled})
        set_needs_generate(conn, True, strand="policy")
    resp: dict = {"ok": True, "job_name": job_name}
    if has_enabled:
        resp["enabled"] = bool(enabled)
    if has_params:
        resp["params"] = clean_params
    return JSONResponse(resp)


_ORG_DISPLAY_BOOL_PARAMS = frozenset({
    "internet_public_src", "internet_public_dst",
})
_ORG_DISPLAY_INT_PARAMS = frozenset({
    "internet_public_src_threshold", "internet_public_dst_threshold",
})


@app.post("/config/display", response_class=JSONResponse)
async def config_display_params(request: Request):
    """Set one or more whitelisted display params (internet_public on/off
    + threshold). Marks needs_generate since these are pipeline-side
    operations applied during the Accumulate stage.
    """
    body = await request.json()
    if not isinstance(body, dict) or not body:
        return JSONResponse({"error": "expected JSON object with params"},
                            status_code=400)
    updates: dict[str, int] = {}
    for key, val in body.items():
        if key in _ORG_DISPLAY_BOOL_PARAMS:
            updates[key] = 1 if val else 0
        elif key in _ORG_DISPLAY_INT_PARAMS:
            try:
                iv = int(val)
            except (TypeError, ValueError):
                return JSONResponse(
                    {"error": f"{key} must be int, got {val!r}"},
                    status_code=400,
                )
            if iv < 1 or iv > 999999:
                return JSONResponse(
                    {"error": f"{key} out of range (1-999999): {iv}"},
                    status_code=400,
                )
            updates[key] = iv
        else:
            return JSONResponse(
                {"error": f"unknown or non-settable param: {key!r}"},
                status_code=400,
            )
    with get_engine().begin() as conn:
        for k, v in updates.items():
            _patch_display_param(conn, k, v)
        set_needs_generate(conn, True, strand="policy")
    return JSONResponse({"ok": True, "updates": updates})


# ── Object editing ─────────────────────────────────────────────────────────

_OBJ_TABLES = {"address": "fw_address_objects", "service": "fw_service_objects"}
_OBJ_GROUP_KINDS = {"address_group", "service_group"}


def _resolve_object(conn, kind: str, obj_id: int) -> tuple[int, str, str] | None:
    """(device_id, name, source) for an object row by kind, else None."""
    if kind in _OBJ_TABLES:
        row = conn.execute(text(
            f"SELECT device_id, name, source FROM {_OBJ_TABLES[kind]} WHERE id = :id"
        ), {"id": obj_id}).fetchone()
    elif kind in _OBJ_GROUP_KINDS or kind == "schedule":
        # Groups + schedules both live in fw_imported_objects, keyed by obj_type.
        row = conn.execute(text(
            "SELECT device_id, name, source FROM fw_imported_objects "
            "WHERE id = :id AND obj_type = :ot"
        ), {"id": obj_id, "ot": kind}).fetchone()
    else:
        return None
    if not row:
        return None
    return int(row[0]), row[1], (row[2] or "import")


async def _update_object(kind: str, obj_id: int, request: Request):
    """Rename and/or describe an object. The description is a fact on the
    row; the rename is a row of the project's name map (model A): the row
    keeps its source name, every reader maps it, and a re-import keeps the
    rename because the map keys on the name the import brings back."""
    body = await request.json()
    name = (body.get("name") or "").strip()
    desc = (body.get("description") or "").strip()
    if not name:
        return JSONResponse({"error": "name required"}, status_code=400)

    if kind in _OBJ_TABLES:
        table = _OBJ_TABLES[kind]
        target_type = "object" if kind == "address" else "service"
        with get_engine().begin() as conn:
            row = conn.execute(text(
                f"SELECT device_id, name, description FROM {table} WHERE id = :id"
            ), {"id": obj_id}).fetchone()
            if not row:
                return JSONResponse({"error": "not found"}, status_code=404)
            device_id, src_name, cur_desc = int(row[0]), row[1], row[2]
            if (desc or None) != (cur_desc or None):
                conn.execute(text(f"""
                    UPDATE {table}
                    SET description = :desc, source = IF(source = 'auto', 'manual', source)
                    WHERE id = :id
                """), {"id": obj_id, "desc": desc or None})
            pid = _ctx_project(conn, request)
            shown = namemap.map_name(namemap.load_name_map(conn, pid), target_type, src_name)
            if name != shown:
                if not pid:
                    return JSONResponse(
                        {"error": "A rename belongs to a project: pick a target first."},
                        status_code=400)
                try:
                    _name_map_set(conn, pid, device_id, target_type, src_name, name)
                except ValueError as e:
                    return JSONResponse({"error": str(e)}, status_code=409)
                set_needs_generate(conn, True, strand="policy")
        return JSONResponse({"ok": True})

    if kind in _OBJ_GROUP_KINDS:
        with get_engine().begin() as conn:
            row = conn.execute(text(
                "SELECT device_id, name, source FROM fw_imported_objects "
                "WHERE id = :id AND obj_type = :ot"
            ), {"id": obj_id, "ot": kind}).fetchone()
            if not row:
                return JSONResponse({"error": "not found"}, status_code=404)
            device_id, src_name, src = int(row[0]), row[1], row[2]
            if src == "synthetic":
                return JSONResponse({"error": "synthetic group is read-only"},
                                    status_code=400)
            # The group's name lives in the same namespace as its element type
            # (address_group -> object refs, service_group -> service refs).
            grp_target = "service" if kind == "service_group" else "object"
            pid = _ctx_project(conn, request)
            shown = namemap.map_name(namemap.load_name_map(conn, pid), grp_target, src_name)
            if name == shown:
                return JSONResponse({"ok": True, "noop": True})
            if not pid:
                return JSONResponse(
                    {"error": "A rename belongs to a project: pick a target first."},
                    status_code=400)
            try:
                _name_map_set(conn, pid, device_id, grp_target, src_name, name)
            except ValueError as e:
                return JSONResponse({"error": str(e)}, status_code=409)
            set_needs_generate(conn, True, strand="policy")
        return JSONResponse({"ok": True})

    return JSONResponse({"error": "invalid kind"}, status_code=400)


async def _delete_object(kind: str, obj_id: int, request: Request):
    """Delete one object, service, group or schedule in this project
    (docs/PROJECT_VIEW_DESIGN.md, P2): the row stays a device fact, the
    project records an exclusion by name, the loaders leave it and its
    memberships out, the generate never sees it. The last-member guard runs
    on the project's view: an object whose removal would empty a rule field,
    a group or a NAT field that this project still uses is refused."""
    if kind not in _OBJ_TABLES and kind not in _OBJ_GROUP_KINDS and kind != "schedule":
        return JSONResponse({"error": "invalid kind"}, status_code=400)
    if kind == "schedule":
        target_type = "schedule"
    elif kind in ("service", "service_group"):
        target_type = "service"
    else:
        target_type = "object"
    with get_engine().begin() as conn:
        pid = _ctx_project_required(conn, request)
        info = _resolve_object(conn, kind, obj_id)
        if not info:
            return JSONResponse({"error": "not found"}, status_code=404)
        device_id, name, source = info
        if source == "synthetic":
            return JSONResponse({"error": "synthetic object is read-only"},
                                status_code=400)
        view = projview.load(conn, pid)
        blk = refmodel.find_delete_blockers(conn, device_id, target_type, {name},
                                            excluded=view.excluded_dict(device_id))
        if name in blk:
            return JSONResponse(
                {"error": ("schedule is still required" if kind == "schedule" else "object is still required"),
                 "blocked": True, "name": name, "reasons": blk[name]}, status_code=409)
        projview.exclude(conn, pid, device_id, projview.UI_KIND[kind], name, label=name)
        _mark_target_configs_stale(conn, "policy", project_id=pid)
    return JSONResponse({"ok": True, "stripped": 0})


