@app.get("/api/objects/{device_id}/search", response_class=JSONResponse)
def objects_search(request: Request, device_id: int, kind: str = "address", q: str = "",
                   limit: int = 500):
    """1b: server-side object search - reach objects BEYOND the inline render cap. The Objects panel
    renders only the first _OBJ_RENDER_CAP per type; this returns JSON matches for `kind` filtered by
    `q` across name / value / description (LIKE), so a huge shared object library (16k+) is fully
    searchable. The client renders editable rows from these (same data-obj-id/handlers). Model A:
    names come back as the project shows them (plus `source_name`), and a term that matches a
    shown name finds the row too."""
    q = (q or "").strip()
    like = f"%{q}%"
    out: list[dict] = []
    mkind = _OBJ_NAME_KIND.get(kind)
    try:
        with get_engine().connect() as conn:
            _pid = _ctx_project(conn, request)
            nm = namemap.load_name_map(conn, _pid)
            # Source names whose SHOWN name matches the term - the LIKE below
            # sees source names only.
            extra = ([s for s, t in (nm.get(mkind) or {}).items() if q.lower() in t.lower()]
                     if (q and mkind) else [])
            if kind == "address":
                sql = ("SELECT id, name, obj_type, value, description, source FROM fw_address_objects "
                       "WHERE device_id = :d AND (:q = '' OR name LIKE :like OR value LIKE :like "
                       "OR description LIKE :like{extra}) ORDER BY name LIMIT :lim")
                for r in _objects_search_rows(conn, sql, device_id, q, like, limit, extra):
                    out.append({"id": r[0], "name": r[1], "type": r[2] or "", "value": r[3] or "",
                                "description": r[4] or "", "source": r[5] or ""})
            elif kind == "service":
                sql = ("SELECT id, name, proto, port, description, source FROM fw_service_objects "
                       "WHERE device_id = :d AND (:q = '' OR name LIKE :like OR port LIKE :like "
                       "OR description LIKE :like{extra}) ORDER BY name LIMIT :lim")
                for r in _objects_search_rows(conn, sql, device_id, q, like, limit, extra):
                    out.append({"id": r[0], "name": r[1], "protocol": r[2] or "", "port": r[3] or "",
                                "description": r[4] or "", "source": r[5] or ""})
            elif kind in ("address_group", "service_group", "url_category", "schedule"):
                sql = ("SELECT id, obj_type, name, value, source FROM fw_imported_objects "
                       "WHERE device_id = :d AND obj_type = :k AND ((source='import' AND import_ts=("
                       "SELECT MAX(import_ts) FROM fw_imported_objects WHERE device_id=:d AND source='import'))"
                       " OR source='synthetic') AND (:q = '' OR name LIKE :like OR value LIKE :like{extra}) "
                       "ORDER BY name LIMIT :lim")
                for r in _objects_search_rows(conn, sql, device_id, q, like, limit, extra, kind=kind):
                    try:
                        val = json.loads(r[3]) if isinstance(r[3], str) else (r[3] or {})
                    except Exception:
                        val = {}
                    o = {"id": r[0], "name": r[2], "source": r[4] or ""}
                    if kind in ("address_group", "service_group"):
                        o.update(val if isinstance(val, dict) else {})
                    else:
                        o["value"] = val
                    out.append(o)
            if _pid:   # the project view: deleted in this project = not found
                _v = projview.load(conn, _pid)
                _xk = projview.UI_KIND.get(kind)
                if _xk in ("group", "service_group"):
                    out = _v.filter_groups(device_id, _xk, out)
                elif _xk:
                    out = _v.filter(device_id, _xk, out)
            if mkind:
                out = namemap.map_named(nm, mkind, out)
    except Exception:
        pass
    return JSONResponse({"objects": out, "count": len(out), "truncated": len(out) >= limit})


_OBJ_NAME_KIND = {"address": "object", "address_group": "object",
                  "service": "service", "service_group": "service"}


def _objects_search_rows(conn, sql: str, device_id: int, q: str, like: str, limit: int,
                         extra: list, kind: str | None = None):
    """Run one objects_search query; `extra` source names (whose shown name
    matched the term) widen the LIKE filter."""
    params = {"d": device_id, "q": q, "like": like, "lim": limit}
    if kind:
        params["k"] = kind
    stmt = text(sql.replace("{extra}", " OR name IN :extra" if extra else ""))
    if extra:
        stmt = stmt.bindparams(bindparam("extra", expanding=True))
        params["extra"] = extra
    return conn.execute(stmt, params).fetchall()


@app.post("/api/objects/{device_id}/bulk-delete", response_class=JSONResponse)
async def object_bulk_delete(device_id: int, request: Request):
    """Delete a set of selected objects in this project, partial-safe.

    Body: ``{"items": [{"kind": str, "id": int}, ...]}``. Query ``?dry_run=1``
    returns the {deletable, blocked} partition WITHOUT writing - the UI shows
    the blast-radius before confirming. The real call re-derives the partition
    server-side (never trusts the client) and records an exclusion per
    deletable item (docs/PROJECT_VIEW_DESIGN.md): the device keeps its rows.
    An object is blocked when it is read-only (synthetic) or its removal
    would empty a rule field / group / NAT field in this project's view (see
    refmodel.find_delete_blockers - selection-aware)."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    items = body.get("items") or []
    if not isinstance(items, list) or not items:
        return JSONResponse({"error": "no items"}, status_code=400)
    dry_run = str(request.query_params.get("dry_run", "")).lower() in ("1", "true", "yes")

    with get_engine().begin() as conn:
        pid = _ctx_project_required(conn, request)
        view = projview.load(conn, pid)
        resolved: list[tuple[str, int, str]] = []   # (kind, id, name)
        blocked: dict[str, list[str]] = {}
        not_found: list = []
        for it in items:
            kind = (it.get("kind") or "").strip()
            oid = it.get("id")
            if oid is None or (kind not in _OBJ_TABLES
                               and kind not in _OBJ_GROUP_KINDS
                               and kind != "schedule"):
                not_found.append(it)
                continue
            info = _resolve_object(conn, kind, int(oid))
            if not info or info[0] != device_id:
                not_found.append(it)
                continue
            _did, name, source = info
            if source == "synthetic":
                blocked.setdefault(name, []).append("read-only (synthetic / pipeline-managed)")
                continue
            resolved.append((kind, int(oid), name))

        selection = {n for _k, _i, n in resolved}
        # Selection-aware guard via the engine on the project's view, all
        # namespaces (names are device-unique). Schedule blocks on a rule's
        # scalar schedule field.
        _excl = view.excluded_dict(device_id)
        for _tt in ("object", "service", "schedule"):
            for nm, reasons in refmodel.find_delete_blockers(
                    conn, device_id, _tt, selection, excluded=_excl).items():
                blocked.setdefault(nm, []).extend(reasons)

        deletable = [(k, i, n) for k, i, n in resolved if n not in blocked]
        partition = {
            "deletable": [{"kind": k, "id": i, "name": n} for k, i, n in deletable],
            "blocked": [{"name": n, "reasons": r} for n, r in blocked.items()],
            "not_found": not_found,
        }
        if dry_run:
            return JSONResponse({"dry_run": True, **partition})

        # the project view (docs/PROJECT_VIEW_DESIGN.md): an exclusion per
        # item, the device keeps its rows, other projects see them unchanged
        for k, _i, n in deletable:
            projview.exclude(conn, pid, device_id, projview.UI_KIND[k], n, label=n)
        if deletable:
            _mark_target_configs_stale(conn, "policy", project_id=pid)

    return JSONResponse({
        "deleted": partition["deletable"],
        "blocked": partition["blocked"],
        "not_found": not_found,
        "stripped": 0,
    })


def _canon_addr_value(v: str) -> str:
    """Same canonicaliser the auto-suppression pipeline uses (main.py:_auto_generate_objects)."""
    if not v:
        return ""
    if "." in v and "/" not in v and "-" not in v and ":" not in v:
        return f"{v}/32"
    return v


def _build_name_to_canon(conn, device_id: int) -> dict:
    """Map every object-name for this device to its canonical value.

    Spans `fw_imported_objects` (newest import_ts + synthetic) plus the
    auto-tables (`fw_address_objects`, `fw_service_objects`). Used to detect
    `member_value_dup` in groups: two distinct member-names that point at
    the same address/service value.
    """
    out: dict[str, tuple] = {}

    try:
        rows = conn.execute(text("""
            SELECT name, obj_type, value FROM fw_imported_objects
             WHERE device_id = :did
               AND obj_type IN ('address', 'service')
               AND ((source = 'import' AND import_ts = (
                       SELECT MAX(import_ts) FROM fw_imported_objects
                        WHERE device_id = :did AND source = 'import'))
                    OR source = 'synthetic')
        """), {"did": device_id}).fetchall()
        for name, obj_type, val_json in rows:
            if not name:
                continue
            try:
                val = json.loads(val_json) if isinstance(val_json, str) else (val_json or {})
            except Exception:
                continue
            if obj_type == "address":
                v = val.get("value") if isinstance(val, dict) else val
                c = _canon_addr_value(str(v or ""))
                if c:
                    out.setdefault(str(name), ("address", c))
            elif obj_type == "service":
                if isinstance(val, dict):
                    p = (val.get("protocol") or "").lower()
                    port = str(val.get("port") or "")
                    if p and port:
                        out.setdefault(str(name), ("service", p, port))
    except Exception:
        pass

    try:
        for name, value in conn.execute(text(
            "SELECT name, value FROM fw_address_objects WHERE device_id = :did"
        ), {"did": device_id}).fetchall():
            if name:
                c = _canon_addr_value(str(value or ""))
                if c:
                    out.setdefault(str(name), ("address", c))
    except Exception:
        pass

    try:
        for name, proto, port in conn.execute(text(
            "SELECT name, proto, port FROM fw_service_objects WHERE device_id = :did"
        ), {"did": device_id}).fetchall():
            if name and proto and port is not None:
                out.setdefault(str(name), ("service", str(proto).lower(), str(port)))
    except Exception:
        pass

    return out


_ADDR_LITERAL_RE = re.compile(r"^[0-9]+(\.[0-9]+){3}(/[0-9]{1,2})?$")


def _resolve_member_canon(member: str, kind: str, name_to_canon: dict):
    """Resolve a raw member-string to its canonical value-tuple, or None.

    First tries name-lookup; falls back to address-literal canonicalisation
    so mixed groups like ["host_x", "10.1.2.3"] (with host_x.value=10.1.2.3)
    still produce a `member_value_dup` flag. Service members are name-only
    (no useful literal form).
    """
    if not member:
        return None
    if member in name_to_canon:
        return name_to_canon[member]
    if kind == "address_group":
        c = _canon_addr_value(member)
        if c and _ADDR_LITERAL_RE.match(c):
            return ("address", c)
    return None


def _compute_group_member_flags(grp_rows, kind: str, name_to_canon: dict) -> dict:
    """Per-row flags `dup_member` and `member_value_dup` for group rows.

    grp_rows: tuples (id, source, obj_type, name, value).
    Synthetic groups skipped - their member-lists are pipeline-derived.
    """
    out: dict[int, list[str]] = {}
    for r in grp_rows:
        rid, src, _otype, _name, val_json = r[0], r[1], r[2], r[3], r[4]
        if src == "synthetic":
            continue
        try:
            val = json.loads(val_json) if isinstance(val_json, str) else (val_json or {})
        except Exception:
            continue
        members = val.get("members") if isinstance(val, dict) else None
        if not isinstance(members, list):
            continue
        members = [str(m) for m in members if m]
        flags: list[str] = []
        if len(members) != len(set(members)):
            flags.append("dup_member")
        canons: dict = {}
        for m in set(members):
            c = _resolve_member_canon(m, kind, name_to_canon)
            if c:
                canons.setdefault(c, []).append(m)
        if any(len(names) >= 2 for names in canons.values()):
            flags.append("member_value_dup")
        if flags:
            out[int(rid)] = flags
    return out


def _lint_kind(rows, used, name_key, value_key):
    """Apply the three flags to a flat list of (id, source, ...) rows.

    rows  : list of tuples - first slot is row-id, second is source
    name_key  : row → str  (used for unused + dup_name)
    value_key : row → hashable | None (used for dup_value, or None to skip)
    """
    name_counts: dict[str, int] = {}
    value_counts: dict = {}
    for row in rows:
        n = name_key(row)
        if n:
            name_counts[n] = name_counts.get(n, 0) + 1
        if value_key is not None:
            v = value_key(row)
            if v is not None:
                value_counts[v] = value_counts.get(v, 0) + 1

    out: dict[int, list[str]] = {}
    for row in rows:
        rid = row[0]
        src = row[1]
        flags: list[str] = []
        n = name_key(row)
        # Synthetic rows are pipeline-managed; suppress 'unused' (they re-seed every
        # run) but keep dup flags so the user can spot collisions with their data.
        if n and n not in used and src != "synthetic":
            flags.append("unused")
        if n and name_counts.get(n, 0) >= 2:
            flags.append("dup_name")
        if value_key is not None:
            v = value_key(row)
            if v is not None and value_counts.get(v, 0) >= 2:
                flags.append("dup_value")
        if flags:
            out[int(rid)] = flags
    return out


@app.get("/api/objects/{device_id}/lint", response_class=JSONResponse)
async def object_lint(request: Request, device_id: int):
    """Compute unused / dup_name / dup_value flags per row, per object kind.

    Row-id keys match the DOM `data-obj-id`:
      - address / service       → fw_address_objects.id / fw_service_objects.id
      - address_group / service_group → fw_imported_objects.id

    Read-only. See feedback_no_page_render_side_effects memory.
    """
    with get_engine().connect() as conn:
        # the project view (docs/PROJECT_VIEW_DESIGN.md): references of this
        # project's view only - a deleted rule or group references nothing
        _pid = _ctx_project(conn, request)
        _excl = projview.load(conn, _pid).excluded_dict(device_id) if _pid else None
        _projects = [_pid] if _pid else None
        # Names referenced as an object/service anywhere - rules (EFFECTIVE stage,
        # closes REF-9), group members, NAT orig/trans, and PBF (closes REF-3/6/7).
        # Shallow: a name inside an otherwise-unused group still counts as used.
        used = {r.name for r in refmodel.collect_references(conn, device_id, projects=_projects, excluded=_excl)
                if "object" in r.targets or "service" in r.targets}

        # Addresses (fw_address_objects).
        addr_rows = conn.execute(text("""
            SELECT id, source, name, value, obj_type
              FROM fw_address_objects WHERE device_id = :did
        """), {"did": device_id}).fetchall()
        addr_flags = _lint_kind(
            list(addr_rows), used,
            name_key=lambda r: r[2] or "",
            value_key=lambda r: _canon_addr_value(r[3] or "") or None,
        )

        # Services (fw_service_objects).
        svc_rows = conn.execute(text("""
            SELECT id, source, name, proto, port
              FROM fw_service_objects WHERE device_id = :did
        """), {"did": device_id}).fetchall()
        svc_flags = _lint_kind(
            list(svc_rows), used,
            name_key=lambda r: r[2] or "",
            value_key=lambda r: ((r[3] or "").lower(), str(r[4] or "")) if r[3] and r[4] is not None else None,
        )

        # Groups (fw_imported_objects, newest import_ts + synthetic).
        # dup_value not computed for groups (see plan §"What V1 doesn't do").
        grp_rows = conn.execute(text("""
            SELECT id, source, obj_type, name, value
              FROM fw_imported_objects
             WHERE device_id = :did
               AND obj_type IN ('address_group', 'service_group')
               AND ((source = 'import' AND import_ts = (
                       SELECT MAX(import_ts) FROM fw_imported_objects
                        WHERE device_id = :did AND source = 'import'))
                    OR source = 'synthetic')
        """), {"did": device_id}).fetchall()
        addr_grp_rows = [r for r in grp_rows if r[2] == "address_group"]
        svc_grp_rows = [r for r in grp_rows if r[2] == "service_group"]
        addr_grp_flags = _lint_kind(
            addr_grp_rows, used,
            name_key=lambda r: r[3] or "",
            value_key=None,
        )
        svc_grp_flags = _lint_kind(
            svc_grp_rows, used,
            name_key=lambda r: r[3] or "",
            value_key=None,
        )
        # Group-member flags (Slice 6): dup_member + member_value_dup.
        name_to_canon = _build_name_to_canon(conn, device_id)
        addr_grp_extra = _compute_group_member_flags(addr_grp_rows, "address_group", name_to_canon)
        svc_grp_extra = _compute_group_member_flags(svc_grp_rows, "service_group", name_to_canon)
        for rid, extras in addr_grp_extra.items():
            addr_grp_flags.setdefault(rid, []).extend(extras)
        for rid, extras in svc_grp_extra.items():
            svc_grp_flags.setdefault(rid, []).extend(extras)

        # Schedules (fw_imported_objects obj_type='schedule', active snapshot).
        # 'used' = names referenced via the rule schedule field (collect_references
        # carries them with target 'schedule'). dup_value not computed (intervals
        # aren't a simple scalar). Mirrors the groups path.
        sched_used = {r.name for r in refmodel.collect_references(conn, device_id, projects=_projects, excluded=_excl)
                      if "schedule" in r.targets}
        sched_rows = conn.execute(text("""
            SELECT id, source, obj_type, name, value
              FROM fw_imported_objects
             WHERE device_id = :did AND obj_type = 'schedule'
               AND ((source = 'import' AND import_ts = (
                       SELECT MAX(import_ts) FROM fw_imported_objects
                        WHERE device_id = :did AND source = 'import'))
                    OR source = 'synthetic')
        """), {"did": device_id}).fetchall()
        sched_flags = _lint_kind(
            list(sched_rows), sched_used,
            name_key=lambda r: r[3] or "",
            value_key=None,
        )

    return JSONResponse({
        "address":       {"row_flags": {str(k): v for k, v in addr_flags.items()}},
        "service":       {"row_flags": {str(k): v for k, v in svc_flags.items()}},
        "address_group": {"row_flags": {str(k): v for k, v in addr_grp_flags.items()}},
        "service_group": {"row_flags": {str(k): v for k, v in svc_grp_flags.items()}},
        "schedule":      {"row_flags": {str(k): v for k, v in sched_flags.items()}},
    })


# ── Object-cleanup merge (Slice 2) ──────────────────────────────────────────
#
# Cascade-rename pattern (analog Slice 6 zones): loser-rows get deleted and
# every reference site for the loser-name gets rewritten to the canonical
# name. `seen`-dedup happens during array rewrites so a Group with
# [_inline_S_tcp_389, _inline_S_tcp_389] merged into [tcp_389] dedupes to
# [tcp_389] (PA push-blocker DM_INLINE_SERVICE_48).
#
# Multi-snapshot discipline: only the newest import_ts is touched in
# fw_imported_rules + fw_imported_objects (Groups). Historical snapshots
# stay immutable.

_OBJ_MERGE_TABLE = {"address": "fw_address_objects", "service": "fw_service_objects"}


def _validate_merge_buckets(conn, device_id: int, kind: str, buckets: list) -> tuple[list, dict[str, str]]:
    """Returns (cleaned_buckets, rename_map old_name → canonical_name).

    Raises ValueError on synthetic / unknown id / canonical==loser. 1-row
    buckets (no losers) are skipped silently (soft validation).
    """
    table = _OBJ_MERGE_TABLE[kind]
    all_ids: set[int] = set()
    for b in buckets:
        cid = (b.get("canonical") or {}).get("id")
        if cid is not None:
            all_ids.add(int(cid))
        for l in b.get("losers") or []:
            lid = l.get("id")
            if lid is not None:
                all_ids.add(int(lid))
    if not all_ids:
        return [], {}
    rows = conn.execute(
        text(f"SELECT id, name, source FROM {table} "
             f"WHERE device_id = :did AND id IN :ids")
            .bindparams(bindparam("ids", expanding=True)),
        {"did": device_id, "ids": list(all_ids)},
    ).fetchall()
    by_id = {int(r[0]): (r[1], r[2]) for r in rows}

    rename: dict[str, str] = {}
    cleaned: list[dict] = []
    for b in buckets:
        cid = int((b.get("canonical") or {}).get("id"))
        losers = b.get("losers") or []
        if not losers:
            continue  # soft-skip 1-row buckets
        if cid not in by_id:
            raise ValueError(f"canonical id {cid} not in {table} for device {device_id}")
        c_name, c_source = by_id[cid]
        if c_source == "synthetic":
            raise ValueError(f"canonical id {cid} is synthetic, not mergeable")
        loser_ids: list[int] = []
        for l in losers:
            lid = int(l.get("id"))
            if lid == cid:
                raise ValueError(f"loser equals canonical (id {lid})")
            if lid not in by_id:
                raise ValueError(f"loser id {lid} not in {table} for device {device_id}")
            l_name, l_source = by_id[lid]
            if l_source == "synthetic":
                raise ValueError(f"loser id {lid} is synthetic, not mergeable")
            if l_name and l_name != c_name:
                rename[l_name] = c_name
            loser_ids.append(lid)
        cleaned.append({
            "canonical_id": cid,
            "canonical_name": c_name,
            "loser_ids": loser_ids,
        })
    return cleaned, rename


@app.post("/api/objects/{device_id}/merge", response_class=JSONResponse)
async def object_merge(device_id: int, request: Request):
    """Merge selected objects into per-bucket canonicals.

    Body shape (plan §"API-Endpoints"):
      {"kind": "address"|"service",
       "buckets": [{"canonical": {"id": int},
                    "losers":    [{"id": int}, ...]}, ...]}

    `?dry_run=1` returns counters + cleaned-buckets without mutating.
    Apply runs everything in one transaction; any error rolls back.
    """
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"error": "invalid JSON body"}, status_code=400)
    kind = body.get("kind")
    if kind not in _OBJ_MERGE_TABLE:
        return JSONResponse({"error": f"invalid kind {kind!r}"}, status_code=400)
    buckets = body.get("buckets") or []
    if not isinstance(buckets, list):
        return JSONResponse({"error": "buckets must be a list"}, status_code=400)
    dry_run = request.query_params.get("dry_run") in ("1", "true", "yes")
    table = _OBJ_MERGE_TABLE[kind]

    # The project view (docs/PROJECT_VIEW_DESIGN.md, D3): a merge is this
    # project's edit. The loser maps to the canonical's shown name (the name
    # map, many-to-one - every reference renders as the canonical, the
    # loser's row folds into it) and leaves the view as an exclusion. The
    # device keeps every row; other projects see them unchanged. The count of
    # references comes from this project's effective view.
    merge_target = "service" if kind == "service" else "object"
    try:
        with get_engine().begin() as conn:
            pid = _ctx_project_required(conn, request)
            cleaned, rename = _validate_merge_buckets(conn, device_id, kind, buckets)
            refs = [r for r in refmodel.collect_references(conn, device_id, projects=[pid])
                    if merge_target in r.targets]
            refs_n = sum(1 for r in refs if r.name in rename)
            deleted = sum(len(b["loser_ids"]) for b in cleaned)
            if dry_run:
                return JSONResponse({"ok": True, "dry_run": True, "buckets": cleaned,
                                     "deleted": deleted, "refs_rewritten": refs_n})
            _nm = namemap.load_name_map(conn, pid)
            for loser, canon in rename.items():
                conn.execute(text("""
                    INSERT INTO fw_project_name_map (project_id, kind, source_name, target_name)
                    VALUES (:p, :k, :s, :t)
                    ON DUPLICATE KEY UPDATE target_name = VALUES(target_name)
                """), {"p": pid, "k": merge_target, "s": loser,
                       "t": namemap.map_name(_nm, merge_target, canon)})
                projview.exclude(conn, pid, device_id, projview.UI_KIND[kind], loser, label=loser, reason="merge")
            _mark_target_configs_stale(conn, "policy", project_id=pid)
        return JSONResponse({"ok": True, "dry_run": False, "deleted": deleted, "refs_rewritten": refs_n})
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


# ── Object-cleanup name-conflict resolver (Slice 3a) ─────────────────────────
#
# Same-name-different-value rows (dup_name flag) collapse to one: user picks
# the winner row, loser rows get deleted. The NAME is preserved → refs in
# rules/groups/NAT continue to bind. But the VALUE they resolve to may have
# shifted, so the dialog surfaces a per-bucket ref-count so the user can
# gauge the semantic blast radius before confirming.
#
# Unlike /merge, no array-rewrites happen - the name is never replaced.

def _count_refs_to_name(conn, device_id: int, name: str) -> dict:
    """Count rule/group/NAT rows that reference `name` for this device.

    Scoped to newest import_ts in fw_imported_rules + fw_imported_objects
    (multi-snapshot discipline, same as the merge path).
    """
    out = {"rules": 0, "groups": 0, "nat": 0}
    if not name:
        return out
    rule_rows = conn.execute(text("""
        SELECT sources, destinations, services FROM fw_imported_rules
         WHERE device_id = :did
           AND import_ts = (SELECT MAX(import_ts) FROM fw_imported_rules WHERE device_id = :did)
    """), {"did": device_id}).fetchall()
    for srcs, dsts, svcs in rule_rows:
        for col in (srcs, dsts, svcs):
            try:
                arr = json.loads(col) if isinstance(col, str) else (col or [])
            except Exception:
                continue
            if isinstance(arr, list) and any(str(x) == name for x in arr):
                out["rules"] += 1
                break
    grp_rows = conn.execute(text("""
        SELECT value FROM fw_imported_objects
         WHERE device_id = :did
           AND obj_type IN ('address_group','service_group')
           AND ((source = 'import' AND import_ts = (
                   SELECT MAX(import_ts) FROM fw_imported_objects
                    WHERE device_id = :did AND source = 'import'))
                OR source = 'synthetic')
    """), {"did": device_id}).fetchall()
    for (val_json,) in grp_rows:
        try:
            val = json.loads(val_json) if isinstance(val_json, str) else (val_json or {})
        except Exception:
            continue
        members = val.get("members") if isinstance(val, dict) else None
        if isinstance(members, list) and any(str(m) == name for m in members):
            out["groups"] += 1
    nat_rows = conn.execute(text("""
        SELECT orig_src, orig_dst, orig_service, trans_src, trans_dst
          FROM fw_nat_rules WHERE device_id = :did
    """), {"did": device_id}).fetchall()
    for osrc, odst, osvc, tsrc, tdst in nat_rows:
        hit = False
        for col in (osrc, odst, osvc):
            try:
                arr = json.loads(col) if isinstance(col, str) else (col or [])
            except Exception:
                continue
            if isinstance(arr, list) and any(str(x) == name for x in arr):
                hit = True
                break
        if not hit and (tsrc == name or tdst == name):
            hit = True
        if hit:
            out["nat"] += 1
    return out


def _validate_name_conflict_buckets(conn, device_id: int, kind: str, buckets: list) -> tuple[list, list[int]]:
    """Returns (cleaned_buckets, all_loser_ids).

    Each cleaned bucket: {"name", "winner_id", "winner_source", "losers": [{id, source}]}.
    Raises ValueError on synthetic / unknown id / winner==loser / name mismatch.
    1-row buckets (no losers) are skipped silently.
    """
    table = _OBJ_MERGE_TABLE[kind]
    all_ids: set[int] = set()
    for b in buckets:
        wid = b.get("winner_id")
        if wid is not None:
            all_ids.add(int(wid))
        for lid in (b.get("loser_ids") or []):
            all_ids.add(int(lid))
    if not all_ids:
        return [], []
    rows = conn.execute(
        text(f"SELECT id, name, source FROM {table} "
             f"WHERE device_id = :did AND id IN :ids")
            .bindparams(bindparam("ids", expanding=True)),
        {"did": device_id, "ids": list(all_ids)},
    ).fetchall()
    by_id = {int(r[0]): (r[1], r[2]) for r in rows}

    cleaned: list[dict] = []
    loser_ids: list[int] = []
    for b in buckets:
        name = b.get("name")
        wid_raw = b.get("winner_id")
        losers = [int(x) for x in (b.get("loser_ids") or [])]
        if not losers:
            continue  # soft-skip
        if wid_raw is None:
            raise ValueError("bucket missing winner_id")
        wid = int(wid_raw)
        if wid not in by_id:
            raise ValueError(f"winner id {wid} not in {table} for device {device_id}")
        w_name, w_source = by_id[wid]
        if w_source == "synthetic":
            raise ValueError(f"winner id {wid} is synthetic, not mergeable")
        if w_name != name:
            raise ValueError(f"winner id {wid} carries name {w_name!r}, bucket says {name!r}")
        ls: list[dict] = []
        for lid in losers:
            if lid == wid:
                raise ValueError(f"loser equals winner (id {lid})")
            if lid not in by_id:
                raise ValueError(f"loser id {lid} not in {table} for device {device_id}")
            l_name, l_source = by_id[lid]
            if l_source == "synthetic":
                raise ValueError(f"loser id {lid} is synthetic, not mergeable")
            if l_name != name:
                raise ValueError(f"loser id {lid} carries name {l_name!r}, bucket says {name!r}")
            ls.append({"id": lid, "source": l_source})
            loser_ids.append(lid)
        cleaned.append({
            "name": name,
            "winner_id": wid,
            "winner_source": w_source,
            "losers": ls,
        })
    return cleaned, loser_ids


@app.post("/api/objects/{device_id}/resolve-name-conflict", response_class=JSONResponse)
async def object_resolve_name_conflict(device_id: int, request: Request):
    """Delete loser-rows for same-name-different-value conflicts; preserve name.

    Body:
      {"kind": "address"|"service",
       "buckets": [{"name": str, "winner_id": int, "loser_ids": [int, ...]}]}

    `?dry_run=1` returns cleaned buckets + per-bucket ref-counts (no mutation).
    Apply deletes losers in a single transaction, then reruns auto-generate.
    """
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"error": "invalid JSON body"}, status_code=400)
    kind = body.get("kind")
    if kind not in _OBJ_MERGE_TABLE:
        return JSONResponse({"error": f"invalid kind {kind!r}"}, status_code=400)
    buckets = body.get("buckets") or []
    if not isinstance(buckets, list):
        return JSONResponse({"error": "buckets must be a list"}, status_code=400)
    dry_run = request.query_params.get("dry_run") in ("1", "true", "yes")
    table = _OBJ_MERGE_TABLE[kind]

    try:
        if dry_run:
            with get_engine().connect() as conn:
                cleaned, _ = _validate_name_conflict_buckets(conn, device_id, kind, buckets)
                for b in cleaned:
                    b["ref_counts"] = _count_refs_to_name(conn, device_id, b["name"])
            deleted = sum(len(b["losers"]) for b in cleaned)
            return JSONResponse({
                "ok": True, "dry_run": True,
                "buckets": cleaned,
                "deleted": deleted,
            })
        with get_engine().begin() as conn:
            cleaned, loser_ids = _validate_name_conflict_buckets(conn, device_id, kind, buckets)
            if loser_ids:
                conn.execute(
                    text(f"DELETE FROM {table} "
                         f"WHERE device_id = :did AND id IN :ids")
                        .bindparams(bindparam("ids", expanding=True)),
                    {"did": device_id, "ids": loser_ids},
                )
            _auto_generate_objects(conn)
        return JSONResponse({
            "ok": True, "dry_run": False,
            "deleted": len(loser_ids),
        })
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


# ── Object-cleanup group-sanitize (Slice 6) ─────────────────────────────────

_GROUP_KIND_TO_OBJ_TYPE = {
    "address_group": "address_group",
    "service_group": "service_group",
}


def _dedup_preserving_order(seq: list) -> tuple[list, list[str], int]:
    """Return (deduped, removed_distinct_names, removed_count).

    Preserves first-occurrence order. `removed_count` is the total number of
    list-slots dropped (a member appearing 3× contributes 2).
    """
    seen: set = set()
    out: list = []
    removed_count = 0
    removed_names: list[str] = []
    removed_seen: set = set()
    for x in seq:
        if x in seen:
            removed_count += 1
            if x not in removed_seen:
                removed_seen.add(x)
                removed_names.append(str(x))
        else:
            seen.add(x)
            out.append(x)
    return out, removed_names, removed_count


def _build_member_addr_lookup(conn, device_id: int) -> dict[str, str]:
    """Map raw IP / CIDR literals to object names for one device.

    Sources fw_address_objects (imported + user + auto). Imported/user rows
    win over auto-rows for Case-A duplicates (two objects same value) via
    ORDER BY + setdefault. Both /32 and bare-IP forms registered so members
    carrying either match the same object.
    """
    lookup: dict[str, str] = {}
    rows = conn.execute(text(
        "SELECT name, value FROM fw_address_objects "
        "WHERE device_id = :did "
        "ORDER BY (source = 'auto') ASC, id ASC"
    ), {"did": device_id}).fetchall()
    for name, value in rows:
        if not name or not value:
            continue
        lookup.setdefault(value, name)
        if value.endswith("/32"):
            lookup.setdefault(value[:-3], name)
        elif "." in value and "/" not in value and "-" not in value and ":" not in value:
            lookup.setdefault(f"{value}/32", name)
    return lookup


@app.post("/api/objects/{device_id}/group-sanitize", response_class=JSONResponse)
async def object_group_sanitize(device_id: int, request: Request):
    """Dedup literal-duplicate member-refs within group `value.members`.

    Body: {"kind": "address_group"|"service_group", "group_ids": [int, ...]}
    `?dry_run=1` returns the diff per group without UPDATE.

    Solo-duplicates only - the member-name appears 2+ times in the array.
    Mixed-name same-value cases (Plan §`member_value_dup`) need Merge by
    Value, not Sanitize.

    Synthetic groups are rejected (pipeline-managed, like Slice 2 merge).
    Malformed-JSON groups are reported per-row without aborting the batch.
    Does NOT call `_auto_generate_objects` - no object-row mutation.
    """
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"error": "invalid JSON body"}, status_code=400)
    kind = body.get("kind")
    if kind not in _GROUP_KIND_TO_OBJ_TYPE:
        return JSONResponse({"error": f"invalid kind {kind!r}"}, status_code=400)
    group_ids = body.get("group_ids") or []
    if not isinstance(group_ids, list) or not all(isinstance(x, int) for x in group_ids):
        return JSONResponse({"error": "group_ids must be a list of ints"}, status_code=400)
    if not group_ids:
        return JSONResponse({"ok": True, "groups": [], "total_groups_changed": 0, "total_removed": 0})
    dry_run = request.query_params.get("dry_run") in ("1", "true", "yes")
    obj_type = _GROUP_KIND_TO_OBJ_TYPE[kind]

    try:
        engine = get_engine()
        ctx = engine.connect() if dry_run else engine.begin()
        with ctx as conn:
            rows = conn.execute(
                text("SELECT id, source, name, value FROM fw_imported_objects "
                     "WHERE device_id = :did AND obj_type = :ot AND id IN :ids")
                    .bindparams(bindparam("ids", expanding=True)),
                {"did": device_id, "ot": obj_type, "ids": group_ids},
            ).fetchall()
            by_id = {int(r[0]): (r[1], r[2], r[3]) for r in rows}

            for gid in group_ids:
                if gid not in by_id:
                    raise ValueError(f"group id {gid} not in {obj_type} for device {device_id}")
                if by_id[gid][0] == "synthetic":
                    raise ValueError(f"group id {gid} is synthetic, not sanitizable")

            addr_lookup = _build_member_addr_lookup(conn, device_id) if kind == "address_group" else {}

            results: list[dict] = []
            total_changed = 0
            total_removed = 0
            total_rewritten = 0
            for gid in group_ids:
                _src, gname, val_json = by_id[gid]
                try:
                    val = json.loads(val_json) if isinstance(val_json, str) else (val_json or {})
                except Exception:
                    results.append({"id": gid, "name": gname, "error": "malformed-json"})
                    continue
                members = val.get("members") if isinstance(val, dict) else None
                if not isinstance(members, list):
                    results.append({"id": gid, "name": gname, "error": "no-members-array"})
                    continue
                before = len(members)
                if addr_lookup:
                    resolved = [addr_lookup.get(m, m) for m in members]
                    rewritten_count = sum(1 for orig, new in zip(members, resolved) if new != orig)
                else:
                    resolved = list(members)
                    rewritten_count = 0
                deduped, removed_names, removed_count = _dedup_preserving_order(resolved)
                after = len(deduped)
                entry = {
                    "id": gid, "name": gname,
                    "before": before, "after": after,
                    "rewritten_count": rewritten_count,
                    "removed_names": removed_names,
                    "removed_count": removed_count,
                }
                if rewritten_count == 0 and removed_count == 0:
                    entry["skipped"] = True
                    results.append(entry)
                    continue
                total_changed += 1
                total_removed += removed_count
                total_rewritten += rewritten_count
                if not dry_run:
                    val["members"] = deduped
                    conn.execute(text(
                        "UPDATE fw_imported_objects SET value = :v "
                        "WHERE device_id = :did AND id = :id"
                    ), {"v": json.dumps(val), "did": device_id, "id": gid})
                results.append(entry)

        return JSONResponse({
            "ok": True, "dry_run": dry_run,
            "groups": results,
            "total_groups_changed": total_changed,
            "total_removed": total_removed,
            "total_rewritten": total_rewritten,
        })
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)


