@app.get("/enrichment/settings/{device_id}", response_class=JSONResponse)
async def enrichment_settings_get(request: Request, device_id: int, platform: str = ""):
    """Return vendor-specific settings for a device+platform combo."""
    engine = get_engine()
    with engine.connect() as conn:
        pid = _project_param(_ctx_project(conn, request))
        row = conn.execute(text(
            "SELECT platform FROM fw_devices WHERE id = :id"
        ), {"id": device_id}).fetchone()
        if not row:
            return JSONResponse({"error": "device not found"}, status_code=404)
        plat = platform or row[0] or ""
        driver_cls = DEPLOY_DRIVERS.get(plat)
        if not driver_cls:
            return JSONResponse({"platform": plat, "settings": [], "error": f"no driver for {plat}"})
        driver = driver_cls()
        defaults = driver.default_settings()

        # Load saved settings for this platform
        saved = {}
        rows = conn.execute(text(
            "SELECT skey, svalue FROM fw_deploy_settings WHERE project_id = :pid AND device_id = :id AND platform = :p"
        ), {"pid": pid, "id": device_id, "p": plat}).fetchall()
        for k, v in rows:
            saved[k] = v

        for s in defaults:
            s["value"] = saved.get(s["key"], s["default"])

        # CP gateway-as-device: the wizard PINS the policy package - the
        # Deploy tab shows the pin read-only and only revalidates it (the
        # free package choice belongs to the manager tier; user decision
        # 2026-09-01). Same resolution as the generate path, so UI and
        # push can never diverge.
        if plat == "checkpoint":
            try:
                _cfg_raw = conn.execute(text(
                    "SELECT config FROM fw_devices WHERE id = :id"
                ), {"id": device_id}).scalar()
                _pin = ((json.loads(_cfg_raw or "{}").get("cp") or {})
                        .get("policy_package") or "").strip()
            except Exception:
                _pin = ""
            if _pin:
                for s in defaults:
                    if s["key"] == "policy_package":
                        s["value"] = _pin
                        s["pinned"] = True

        return JSONResponse({"platform": plat, "settings": defaults})


@app.post("/deploy/cp-pin/revalidate/{device_id}", response_class=JSONResponse)
async def deploy_cp_pin_revalidate(device_id: int):
    """Re-check a CP gateway device's pinned policy package against the
    management server. Ground truth = the gateway object's
    policy.access-policy-name (show-gateways-and-servers) - the same
    source the registration wizard uses. Updates the stored pin when the
    gateway moved packages on the SC; never offers a free choice."""
    engine = get_engine()
    with engine.begin() as conn:
        row = conn.execute(text(
            "SELECT platform, mgmt_ip, mgmt_port, api_key, host_name, "
            "display_name, config FROM fw_devices WHERE id = :id"
        ), {"id": device_id}).mappings().fetchone()
        if not row or row["platform"] != "checkpoint":
            return JSONResponse({"error": "not a Check Point gateway device"},
                                status_code=404)
        try:
            cfg = json.loads(row["config"] or "{}")
        except Exception:
            cfg = {}
        cp_cfg = cfg.get("cp") or {}
        pin = (cp_cfg.get("policy_package") or "").strip()
        mgmt_ip = ((cp_cfg.get("mgmt") or {}).get("ip") or row["mgmt_ip"] or "").strip()
        mgmt_port = (cp_cfg.get("mgmt") or {}).get("port") or 443
        if not (mgmt_ip and row["api_key"]):
            return JSONResponse({"error": "no management address / API key"},
                                status_code=400)
        try:
            sid, base_url = _cp_get_sid(mgmt_ip, mgmt_port,
                                        secrets_util.reveal(row["api_key"]))
            from deploy.checkpoint import _call as cp_call
            with fail_fast_transport():
                gw_resp = cp_call(base_url, sid, "show-gateways-and-servers",
                                  {"limit": 200, "details-level": "full"})
        except Exception as exc:
            _cp_invalidate_sid(mgmt_ip, mgmt_port, row["api_key"])
            return JSONResponse({"error": f"management lookup failed: {exc}"},
                                status_code=502)
        names = {row["host_name"], row["display_name"]}
        gw = next((o for o in (gw_resp.get("objects") or [])
                   if o.get("name") in names
                   or (o.get("ipv4-address") or "") == (row["mgmt_ip"] or "")),
                  None)
        if not gw:
            return JSONResponse({"error": "gateway object not found on the "
                                          "management server, re-register the device"},
                                status_code=404)
        actual = ((gw.get("policy") or {}).get("access-policy-name") or "").strip()
        if not actual:
            return JSONResponse({"error": "gateway has no access policy "
                                          "assigned on the management server"},
                                status_code=409)
        if actual == pin:
            return JSONResponse({"ok": True, "package": pin, "changed": False})
        cfg.setdefault("cp", {})["policy_package"] = actual
        conn.execute(text("UPDATE fw_devices SET config = :c WHERE id = :id"),
                     {"c": json.dumps(cfg), "id": device_id})
        return JSONResponse({"ok": True, "package": actual, "changed": True,
                             "previous": pin})


@app.get("/enrichment/settings/{device_id}/options/{key}", response_class=JSONResponse)
async def enrichment_settings_options(request: Request, device_id: int, key: str, platform: str = "",
                                      cp_package: str = ""):
    """Live option lookup for a ``select_remote`` setting.

    Calls ``driver.setting_options(device, key, settings)`` so the UI can
    populate dropdowns from the actual device (CP packages/layers, PA-OS
    vsys, Forti VDOMs …). Pass platform explicitly to disambiguate when a
    device has both source + target roles.
    """
    engine = get_engine()
    with engine.connect() as conn:
        pid = _project_param(_ctx_project(conn, request))
        row = conn.execute(text(
            "SELECT platform, mgmt_ip, mgmt_port, api_key, "
            "host_name, display_name, role, gaia_user, gaia_password, config, device_kind "
            "FROM fw_devices WHERE id = :id"
        ), {"id": device_id}).fetchone()
        if not row:
            return JSONResponse({"error": "device not found"}, status_code=404)
        plat = platform or row[0] or ""
        driver_cls = DEPLOY_DRIVERS.get(plat)
        if not driver_cls:
            return JSONResponse({"error": f"no driver for {plat}", "options": []})
        if not row[3]:
            return JSONResponse({"error": "no API key configured", "options": []})
        if not row[1]:
            return JSONResponse({"error": "no management IP configured", "options": []})

        device = {
            "id": device_id, "platform": row[0],
            "mgmt_ip": row[1], "mgmt_port": row[2], "api_key": secrets_util.reveal(row[3]),
            "host_name": row[4], "display_name": row[5], "role": row[6],
            "gaia_user": row[7], "gaia_password": secrets_util.reveal(row[8]), "config": row[9],
        }
        # CP MANAGER-source target: the row has no config.cp.mgmt.ip - inject the egress
        # config (mgmt.ip + the header package's DOMAIN) so show-packages/-layers log into
        # the right context (same as the TP + push paths).
        if plat == "checkpoint" and row[10] == "manager-source":
            device, _cperr = _cp_manager_egress_device(
                engine, device, device_id, strand="policy", package_label=cp_package)
            if _cperr:
                return JSONResponse({"error": f"CP manager target: {_cperr}", "options": []})

        # Saved settings provide context for dependent dropdowns
        # (e.g. CP layer-list scoped to the chosen policy_package).
        saved: dict[str, str] = {}
        srows = conn.execute(text(
            "SELECT skey, svalue FROM fw_deploy_settings WHERE project_id = :pid AND device_id = :id AND platform = :p"
        ), {"pid": pid, "id": device_id, "p": plat}).fetchall()
        for k, v in srows:
            saved[k] = v

    driver = driver_cls()
    try:
        opts = driver.setting_options(device=device, key=key, settings=saved)
    except NotImplementedError as e:
        return JSONResponse({"error": str(e), "options": []}, status_code=400)
    except Exception as e:
        import logging
        logging.getLogger(__name__).exception(
            "setting_options failed for %s/%s", plat, key
        )
        return JSONResponse({"error": f"{type(e).__name__}: {e}", "options": []})
    return JSONResponse({"options": list(opts)})


@app.post("/enrichment/settings/{device_id}", response_class=JSONResponse)
async def enrichment_settings_save(device_id: int, request: Request):
    """Save vendor-specific settings for a device."""
    body = await request.json()
    platform = body.get("platform", "")
    settings = body.get("settings", {})
    if not platform:
        return JSONResponse({"error": "platform required"}, status_code=400)
    engine = get_engine()
    with engine.begin() as conn:
        pid = _ctx_project_required(conn, request)
        exists = conn.execute(text(
            "SELECT 1 FROM fw_devices WHERE id = :id"
        ), {"id": device_id}).fetchone()
        if not exists:
            return JSONResponse({"error": "device not found"}, status_code=404)
        for key, value in settings.items():
            conn.execute(text("""
                INSERT INTO fw_deploy_settings (project_id, device_id, platform, skey, svalue)
                VALUES (:pid, :did, :p, :k, :v)
                ON DUPLICATE KEY UPDATE svalue = :v
            """), {"pid": pid, "did": device_id, "p": platform, "k": key, "v": value or ""})
        # A push-destination setting shapes the render: the project's target
        # configuration is outdated (docs/DEPLOY_PAGE_DESIGN.md, E4).
        _mark_target_configs_stale(conn, None, project_id=pid)
    return JSONResponse({"ok": True})


def _pano_dg_chain(conn, manager_id: int, dg_name: str) -> list[str]:
    """Device-group inheritance chain for `dg_name` under a Panorama manager,
    nearest-first (the DG, then its parent DGs), EXCLUDING shared (callers read
    /config/shared separately). [] if dg_name is not a device-group scope of
    this manager. Lets a target-profile catalog show exactly what a rule in that
    device-group resolves against (its own + inherited profiles), not the empty
    firewall vsys."""
    rows = conn.execute(text(
        "SELECT s.scope_device_id AS sid, s.parent_scope_device_id AS pid, "
        "       s.scope_type AS st, COALESCE(d.display_name, d.host_name) AS nm "
        "FROM fw_scopes s JOIN fw_devices d ON d.id = s.scope_device_id "
        "WHERE s.manager_device_id = :m"), {"m": manager_id}).mappings().all()
    by_id = {r["sid"]: r for r in rows}
    cur = next((r for r in rows if r["nm"] == dg_name and r["st"] == "device-group"), None)
    chain: list[str] = []
    seen: set = set()
    while cur is not None and cur["sid"] not in seen:
        seen.add(cur["sid"])
        if cur["st"] != "device-group":
            break  # reached shared / a non-DG parent - shared is added separately
        chain.append(cur["nm"])
        cur = by_id.get(cur["pid"])
    return chain


def _pano_catalog_scopes(target_id: int, scope: str) -> list[str] | None:
    """Resolve the ``scope`` query param (a device-group name) to a DG chain for
    a manager-source (Panorama) target, else None. Shared helper for the target
    profile-catalog endpoints so a Panorama shows device-group-scoped profiles."""
    dg = (scope or "").strip()
    if not dg:
        return None
    with get_engine().connect() as conn:
        if conn.execute(text("SELECT device_kind FROM fw_devices WHERE id = :id"),
                        {"id": target_id}).scalar() != "manager-source":
            return None
        return _pano_dg_chain(conn, target_id, dg) or None


@app.get("/enrichment/security-profiles/{target_id}", response_class=JSONResponse)
async def enrichment_security_profiles(target_id: int, scope: str = "", cp_package: str = ""):
    """Read the target's per-rule attachable profile catalog.

    Driver-decided shape: returns {category: [name, ...]} where categories are
    vendor-specific (e.g. PA: antivirus / anti-spyware / vulnerability /
    url-filtering / file-blocking / wildfire-analysis / dns-security /
    profile-group). Read-only - first iteration of the vendor-specific
    Enrichment view.

    ``scope`` (query): for a Panorama target, the destination device-group so the
    catalog is scoped to that DG's chain + shared (instead of the empty vsys).
    """
    engine = get_engine()
    with engine.connect() as conn:
        row = conn.execute(text(
            "SELECT id, host_name, display_name, platform, mgmt_ip, mgmt_port, "
            "       api_key, gaia_user, gaia_password, config, device_kind "
            "FROM fw_devices WHERE id = :id"
        ), {"id": target_id}).fetchone()
    if not row:
        return JSONResponse({"error": "target not found"}, status_code=404)
    platform = row[3] or ""
    driver_cls = DEPLOY_DRIVERS.get(platform)
    if not driver_cls:
        return JSONResponse({"error": f"no driver for platform {platform!r}"},
                            status_code=400)
    driver = driver_cls()
    device = {
        "id": row[0], "host_name": row[1], "display_name": row[2],
        "platform": platform, "mgmt_ip": row[4], "mgmt_port": row[5],
        "api_key": secrets_util.reveal(row[6]), "gaia_user": row[7], "gaia_password": secrets_util.reveal(row[8]),
        "config": row[9],
    }
    if platform == "checkpoint" and row[10] == "manager-source":
        device, _cperr = _cp_manager_egress_device(
            engine, device, target_id, strand="policy", package_label=cp_package)
        if _cperr:
            return JSONResponse({"error": f"CP manager target: {_cperr}"}, status_code=400)
    _kw = {"device": device}
    _scopes = _pano_catalog_scopes(target_id, scope)
    if _scopes:
        _kw["scopes"] = _scopes
    try:
        catalog = driver.list_security_profiles(**_kw)
    except NotImplementedError as e:
        return JSONResponse({"error": str(e), "supported": False},
                            status_code=400)
    except Exception as e:
        return JSONResponse({"error": f"read failed: {e}"}, status_code=502)
    return JSONResponse({"target_id": target_id, "platform": platform,
                         "catalog": catalog})


# ── CP Threat-Prevention enrichment ──────────────────────────────
#
# CP TP is a separate rulebase per TP-Layer (see
# project_cp_tp_separate_rulebase). Gateshift model: user picks (TP-Layer,
# Strategy, Params); generator deterministically produces TP-rules;
# Preview = Apply (frontend-only). Push happens via Deploy-tab and
# re-runs the same generator.

def _tp_load_target_device(target_id: int, cp_package: str = "") -> dict | tuple[JSONResponse, None]:
    """Load target device dict for TP endpoints.

    Returns ``device`` dict on success, or ``(JSONResponse, None)`` to
    short-circuit with an error. CP drivers need config + gaia creds in
    the device dict (see feedback_cp_device_dict_needs_config).

    For a CP MANAGER-source target (MDS/SmartCenter) the row has no
    config.cp.mgmt.ip - inject the egress config (mgmt.ip + the selected
    package's domain) exactly like the push path, so the driver logs into
    the right domain to read its TP layers/profiles.
    """
    engine = get_engine()
    with engine.connect() as conn:
        row = conn.execute(text(
            "SELECT id, host_name, display_name, platform, mgmt_ip, mgmt_port, "
            "       api_key, gaia_user, gaia_password, config, device_kind "
            "FROM fw_devices WHERE id = :id"
        ), {"id": target_id}).fetchone()
    if not row:
        return JSONResponse({"error": "target not found"}, status_code=404), None
    device = {
        "id": row[0], "host_name": row[1], "display_name": row[2],
        "platform": row[3] or "", "mgmt_ip": row[4], "mgmt_port": row[5],
        "api_key": secrets_util.reveal(row[6]), "gaia_user": row[7], "gaia_password": secrets_util.reveal(row[8]),
        "config": row[9],
    }
    if (device["platform"] == "checkpoint" and row[10] == "manager-source"):
        device, err = _cp_manager_egress_device(
            engine, device, target_id, strand="policy", package_label=cp_package)
        if err:
            return JSONResponse(
                {"error": f"CP manager target: {err}", "supported": True},
                status_code=400), None
    return device


def _tp_get_driver(device: dict):
    """Resolve driver class; returns (driver, None) or (None, JSONResponse)."""
    platform = device.get("platform") or ""
    driver_cls = DEPLOY_DRIVERS.get(platform)
    if not driver_cls:
        return None, JSONResponse(
            {"error": f"no driver for platform {platform!r}", "supported": False},
            status_code=400,
        )
    return driver_cls(), None


@app.get("/enrichment/threat-layers/{target_id}", response_class=JSONResponse)
async def enrichment_threat_layers(target_id: int, cp_package: str = ""):
    """List Threat-Prevention layers on the target.

    Drivers without a TP-rulebase concept return 400 supported=False; the
    UI hides the TP sub-tab for those.
    """
    res = _tp_load_target_device(target_id, cp_package)
    if isinstance(res, tuple):
        return res[0]
    device = res
    driver, err = _tp_get_driver(device)
    if err:
        return err
    try:
        layers = driver.list_threat_layers(device=device)
    except NotImplementedError as e:
        return JSONResponse({"error": str(e), "supported": False},
                            status_code=400)
    except Exception as e:
        return JSONResponse({"error": f"read failed: {e}"}, status_code=502)
    # Default layer for the UI preselect: the layer that belongs to the
    # target's POLICY PACKAGE (finding 2026-09-16: without a default the
    # user configured a foreign package's layer alongside the right one,
    # pushing identical rules into both).
    _pkg = (cp_package.split("/", 1)[-1] if cp_package else "").strip()
    if not _pkg:
        try:
            _pkg = ((json.loads(device.get("config") or "{}").get("cp") or {})
                    .get("policy_package") or "").strip()
        except Exception:
            _pkg = ""
    default_layer = None
    if _pkg:
        for _l in layers:
            _nm = (_l.get("name") or "")
            if _nm == f"{_pkg} Threat Prevention" or _nm.startswith(_pkg + " "):
                default_layer = _nm
                break
    return JSONResponse({"target_id": target_id, "platform": device["platform"],
                         "layers": layers, "default_layer": default_layer})


