@app.get("/enrichment/tp-config/{target_id}", response_class=JSONResponse)
async def enrichment_tp_config_list(request: Request, target_id: int):
    """Return all saved (layer, strategy, params) rows for this target."""
    engine = get_engine()
    with engine.connect() as conn:
        pid = _project_param(_ctx_project(conn, request))
        rows = conn.execute(text(
            "SELECT layer_name, strategy, params_json, updated_at "
            "FROM fw_tp_layer_config WHERE project_id = :pid AND device_id = :id "
            "ORDER BY layer_name"
        ), {"pid": pid, "id": target_id}).fetchall()
    out = []
    for layer_name, strategy, params_json, updated_at in rows:
        try:
            params = json.loads(params_json) if isinstance(params_json, str) else (params_json or {})
        except Exception:
            params = {}
        out.append({
            "layer_name": layer_name,
            "strategy":   strategy,
            "params":     params,
            "updated_at": updated_at.isoformat() if updated_at else None,
        })
    return JSONResponse({"target_id": target_id, "configs": out})


def _tp_load_source_data(conn, source_id: int,
                         project_id: int | None = None,
                         name_map: dict | None = None) -> tuple[list[dict], list[dict], list[dict]]:
    """Minimal source-data load for TP generation: rules + addr objects/groups.

    Mirrors the load logic in /deploy/{source_id}/generate but only loads
    the bits ``generate_tp_rules`` needs. Keeps the TP endpoint independent
    of the heavier full-deploy data pipeline.
    """
    src = conn.execute(text(
        "SELECT host_name, display_name FROM fw_devices WHERE id = :id"
    ), {"id": source_id}).fetchone()
    if not src:
        return [], [], []
    source_name = src[1] or src[0]

    address_objects: list[dict] = []
    address_groups: list[dict] = []
    try:
        obj_rows = conn.execute(text("""
            SELECT obj_type, name, value FROM fw_imported_objects
            WHERE device_id = :id
              AND ((source = 'import' AND import_ts = (
                      SELECT MAX(import_ts) FROM fw_imported_objects
                      WHERE device_id = :id AND source = 'import'))
                   OR source = 'synthetic')
        """), {"id": source_id}).fetchall()
        for otype, oname, val_json in obj_rows:
            val = json.loads(val_json) if isinstance(val_json, str) else (val_json or {})
            obj = {"name": oname, "value": val}
            if otype == "address":
                address_objects.append(obj)
            elif otype == "address_group":
                address_groups.append(obj)
    except Exception:
        pass
    try:
        addr_rows = conn.execute(text(
            "SELECT name, value, obj_type FROM fw_address_objects WHERE device_id = :id"
        ), {"id": source_id}).fetchall()
        seen = {o["name"] for o in address_objects}
        for aname, aval, _atype in addr_rows:
            if aname in seen or not aval:
                continue
            body = (
                {"type": "ip-netmask", "value": aval} if "/" in aval
                else {"type": "ip-range", "value": aval}
                if "-" in aval and aval.count(".") >= 6
                else {"type": "ip-netmask", "value": f"{aval}/32"}
            )
            address_objects.append({"name": aname, "value": body})
            seen.add(aname)
    except Exception:
        pass

    display = load_display(conn)
    r = _fetch_rules_and_devices(conn, page=1, page_size=100000,
                                 device=source_name, display=display,
                                 project_id=project_id, name_map=name_map)
    rules: list[dict] = []
    for group_rules in r.get("devices", {}).values():
        rules.extend(group_rules)
    if name_map:
        address_objects = namemap.map_named(name_map, "object", address_objects)
        address_groups = namemap.map_named(name_map, "object", address_groups)
    return rules, address_objects, address_groups


def _load_imported_tp_rules(conn, device_id: int) -> list[dict]:
    """CP source TP rows (fw_imported_tp_rules) as generator-shaped dicts
    for strategy 'source'. Empty for non-CP sources - the generator then
    refuses the strategy with a clear message."""
    out: list[dict] = []
    try:
        rows = conn.execute(text(
            "SELECT source_layer, seq, rule_name, exception_of, enabled, "
            "       action_profile, src_json, dst_json, svc_json, "
            "       protected_scope_json, protections_json, track_json, "
            "       comments "
            "FROM fw_imported_tp_rules WHERE device_id = :id "
            "ORDER BY source_layer, seq"
        ), {"id": device_id}).fetchall()
    except Exception:
        return out

    def _j(v, default):
        try:
            return json.loads(v) if isinstance(v, str) else (v or default)
        except Exception:
            return default

    for r in rows:
        out.append({
            "source_layer":    r[0],
            "seq":             r[1],
            "rule_name":       r[2],
            "exception_of":    r[3],
            "enabled":         bool(r[4]),
            "action_profile":  r[5],
            "src":             _j(r[6], []),
            "dst":             _j(r[7], []),
            "svc":             _j(r[8], []),
            "protected_scope": _j(r[9], []),
            "protections":     _j(r[10], []),
            "track":           _j(r[11], {}),
            "comments":        r[12],
        })
    return out


@app.post("/enrichment/tp/apply", response_class=JSONResponse)
async def enrichment_tp_apply(request: Request):
    """Save TP-Layer config + return generated TP-rules preview.

    Body: ``{"target_id": int, "source_id": int (optional, defaults to
    target_id), "layer_name": str, "strategy": str, "params": dict}``.

    Validates layer_name + params.default_profile against the live catalog
    (refuse if either is missing). Persists to ``fw_tp_layer_config`` and
    returns the generated TP-rules. Frontend only - does NOT push to device.
    """
    try:
        body = await request.json()
    except Exception:
        body = {}
    target_id = body.get("target_id")
    if not isinstance(target_id, int):
        return JSONResponse({"error": "target_id required (int)"}, status_code=400)
    source_id = body.get("source_id")
    if not isinstance(source_id, int):
        source_id = target_id
    layer_name = (body.get("layer_name") or "").strip()
    strategy   = (body.get("strategy") or "").strip()
    params     = body.get("params") or {}
    if not layer_name or not strategy or not isinstance(params, dict):
        return JSONResponse(
            {"error": "layer_name, strategy, params (dict) required"},
            status_code=400,
        )

    res = _tp_load_target_device(target_id, (body.get("cp_package") or ""))
    if isinstance(res, tuple):
        return res[0]
    device = res
    driver, err = _tp_get_driver(device)
    if err:
        return err

    # Catalog-validation: refuse Apply if layer or profile vanished
    try:
        layers = driver.list_threat_layers(device=device)
    except NotImplementedError as e:
        return JSONResponse({"error": str(e), "supported": False},
                            status_code=400)
    except Exception as e:
        return JSONResponse({"error": f"layer catalog read failed: {e}"},
                            status_code=502)
    if not any(l["name"] == layer_name for l in layers):
        return JSONResponse(
            {"error": f"layer {layer_name!r} not found on target",
             "available_layers": [l["name"] for l in layers]},
            status_code=400,
        )

    if strategy in ("security-ruleset", "baseline", "protected-assets"):
        default_profile = (params.get("default_profile") or "").strip()
        if not default_profile:
            return JSONResponse(
                {"error": f"params.default_profile required for strategy {strategy!r}"},
                status_code=400,
            )
        try:
            profiles = driver.list_threat_profiles(device=device)
        except Exception as e:
            return JSONResponse({"error": f"profile catalog read failed: {e}"},
                                status_code=502)
        if not any(p["name"] == default_profile for p in profiles):
            return JSONResponse(
                {"error": f"profile {default_profile!r} not found on target",
                 "available_profiles": [p["name"] for p in profiles]},
                status_code=400,
            )

    # Load source-data + generate
    engine = get_engine()
    with engine.begin() as conn:
        # Saving a layer config is a write for the (source, target) pair.
        pid = _project_for_pair(conn, source_id, target_id, create=True)
        if pid is None:
            return JSONResponse({"error": "source or target device not found"},
                                status_code=404)
        rules, addr_obj, addr_grp = _tp_load_source_data(
            conn, source_id, project_id=pid, name_map=namemap.load_name_map(conn, pid))
        imported_tp = _load_imported_tp_rules(conn, source_id)
        try:
            tp_rules = driver.generate_tp_rules(
                layer_name=layer_name,
                strategy=strategy,
                params=params,
                rules=rules,
                zones=[],
                address_objects=addr_obj,
                address_groups=addr_grp,
                imported_tp=imported_tp,
            )
        except NotImplementedError as e:
            return JSONResponse({"error": str(e), "supported": False},
                                status_code=400)
        except ValueError as e:
            return JSONResponse({"error": str(e)}, status_code=400)
        except Exception as e:
            return JSONResponse({"error": f"generate failed: {e}"},
                                status_code=500)

        conn.execute(text("""
            INSERT INTO fw_tp_layer_config (project_id, device_id, layer_name, strategy, params_json)
            VALUES (:pid, :did, :ln, :st, :pj)
            ON DUPLICATE KEY UPDATE
              strategy    = VALUES(strategy),
              params_json = VALUES(params_json)
        """), {
            "pid": pid, "did": target_id, "ln": layer_name, "st": strategy,
            "pj":  json.dumps(params, separators=(",", ":")),
        })

    return JSONResponse({
        "target_id":  target_id,
        "source_id":  source_id,
        "layer_name": layer_name,
        "strategy":   strategy,
        "params":     params,
        "tp_rules":   tp_rules,
        "rule_count": len(tp_rules),
    })


@app.get("/enrichment/tp/preview/{target_id}/{layer_name:path}",
         response_class=JSONResponse)
async def enrichment_tp_preview(request: Request, target_id: int, layer_name: str,
                                source_id: int | None = None, cp_package: str = ""):
    """Regenerate TP-rules preview from the saved config for this layer.

    Use case: user re-opens the sub-tab; we re-run the generator against
    the saved (strategy, params) so the preview matches what Push will do.

    Query param ``source_id`` selects the device whose access-rules drive
    the generator (cross-device deploys). Defaults to ``target_id`` for the
    self-deploy case.
    """
    src_id = source_id if isinstance(source_id, int) else target_id
    engine = get_engine()
    with engine.connect() as conn:
        pid = _project_param(_page_project(conn, request, src_id, target_id))
        row = conn.execute(text(
            "SELECT strategy, params_json FROM fw_tp_layer_config "
            "WHERE project_id = :pid AND device_id = :did AND layer_name = :ln"
        ), {"pid": pid, "did": target_id, "ln": layer_name}).fetchone()
    if not row:
        return JSONResponse(
            {"error": f"no saved config for layer {layer_name!r}"},
            status_code=404,
        )
    strategy = row[0]
    try:
        params = json.loads(row[1]) if isinstance(row[1], str) else (row[1] or {})
    except Exception:
        params = {}

    res = _tp_load_target_device(target_id, cp_package)
    if isinstance(res, tuple):
        return res[0]
    device = res
    driver, err = _tp_get_driver(device)
    if err:
        return err

    with get_engine().connect() as conn:
        rules, addr_obj, addr_grp = _tp_load_source_data(
            conn, src_id, project_id=pid, name_map=namemap.load_name_map(conn, pid))
        imported_tp = _load_imported_tp_rules(conn, src_id)
    try:
        tp_rules = driver.generate_tp_rules(
            layer_name=layer_name,
            strategy=strategy,
            params=params,
            rules=rules,
            zones=[],
            address_objects=addr_obj,
            address_groups=addr_grp,
            imported_tp=imported_tp,
        )
    except Exception as e:
        return JSONResponse({"error": f"generate failed: {e}"}, status_code=500)

    # Drift-Detection: cross-check saved (layer, default_profile) against the
    # live target catalog. The user may have renamed/removed the layer or
    # deleted the profile in SmartConsole since Apply. Surface as advisory
    # flags so the UI can render a "stale" badge without breaking the
    # preview itself - Push refuses cleanly via the same checks at push-time.
    drift: dict = {"layer_missing": False, "profile_missing": False}
    try:
        layers = driver.list_threat_layers(device=device)
        if not any(l.get("name") == layer_name for l in layers):
            drift["layer_missing"] = True
            drift["available_layers"] = [l.get("name") for l in layers
                                         if l.get("name")]
    except Exception as e:
        drift["layer_check_error"] = str(e)
    if strategy == "source":
        # Advisory drift for the source strategy: the saved source layer
        # can vanish after a re-import (layer renamed/removed at source).
        _have = {(r.get("source_layer") or "").strip()
                 for r in imported_tp}
        _want = (params.get("source_layer") or "").strip()
        if _want and _want not in _have:
            drift["source_layer_missing"] = True
            drift["available_source_layers"] = sorted(x for x in _have if x)
    if strategy in ("security-ruleset", "baseline", "protected-assets"):
        prof = (params.get("default_profile") or "").strip()
        if prof:
            try:
                profiles = driver.list_threat_profiles(device=device)
                if not any(p.get("name") == prof for p in profiles):
                    drift["profile_missing"] = True
                    drift["available_profiles"] = [p.get("name")
                                                   for p in profiles
                                                   if p.get("name")]
            except Exception as e:
                drift["profile_check_error"] = str(e)

    return JSONResponse({
        "target_id":  target_id,
        "source_id":  src_id,
        "layer_name": layer_name,
        "strategy":   strategy,
        "params":     params,
        "tp_rules":   tp_rules,
        "rule_count": len(tp_rules),
        "drift":      drift,
    })


